/**
 * Step 4 (Monte Carlo): single template treatment shared across N fields.
 *
 * MC's "treatment count" equals the number of Fields generated by Step 2's
 * spatial config — so Step 4 is just one shared protocol bundle. The
 * single Treatment record we create here gets attached to the draft once
 * per field (one WizardDraftTreatment row per pair), and the run pipeline
 * (monte_carlo_service) materialises one DSSAT treatment per pair.
 *
 * Per-field in-situ planting was previously a separate block at the top
 * of this step. It now lives inside the protocol editor's Planting &
 * Harvest section as the Auto/Fixed Date toggle, available across every
 * experiment type (not just MC). The resolve-at-lock pass below picks up
 * Auto-mode pairs and pre-resolves their dates against the in-situ
 * raster before committing — a failure aborts the lock and surfaces a
 * clear error.
 */

import {h, clear} from '../dom.js';
import {treatments as treatmentsAPI} from '../api.js';
import {mount as mountEditor} from './protocol_editor.js';
import {
    resolveAutoPlantingDatesForPairs,
    pruneResolvedPlantingDates,
} from '../auto_planting_resolver.js';

let editor = null;
let currentValue = null;

export async function render(root, store) {
    clear(root);
    const stepState = store.getStep('step4') || {};
    const seed = stepState.template || {};
    const year = (store.getStep('step1') || {}).year;

    const panel = h('div', {class: 'wizard-step-panel'});
    panel.appendChild(h('h2', {class: 'step-title'}, 'Monte Carlo Template'));
    panel.appendChild(h('p', {class: 'step-description'},
        'Build the single shared protocol that runs at every grid point. '
        + 'Use Auto in the Planting & Harvest section to resolve a per-field '
        + 'planting date from an in-situ raster (with a Coverage button to '
        + 'preview which fields are covered before clicking Next).'));

    const editorHost = h('div');
    panel.appendChild(editorHost);
    root.appendChild(panel);

    editor = mountEditor(editorHost, {
        value: seed,
        onChange: (val) => {
            currentValue = val;
            store.setStep('step4', {template: val});
        },
        options: {year, fields: store.fields},
    });
    currentValue = editor.getValue();
}

export function validate(store) {
    const v = currentValue || (store.getStep('step4') || {}).template;
    if (!v || !v.crop_code) {
        return {ok: false, message: 'Pick a crop in the template protocol.'};
    }
    if (!v.planting || !v.planting.mode) {
        return {ok: false, message: 'Pick a planting-date mode (Auto or Fixed Date).'};
    }
    if (v.planting.mode === 'fixed' && v.planting.pdoy == null) {
        return {ok: false, message: 'Pick a fixed planting date.'};
    }
    if (v.planting.mode === 'auto' && !v.planting.auto_source) {
        return {ok: false, message: 'Pick an Auto planting-date source.'};
    }
    return {ok: true};
}

/** Lock hook: persist the single template Treatment + attach + write pairs.
 *
 * MC is N fields × 1 template treatment. Each pair = one DSSAT treatment
 * row in FILEX *TREATMENTS — even though the protocol is shared, the
 * (Field, Treatment) pairing makes the run-time materialisation explicit.
 * For Auto-mode templates, every pair is resolved against the in-situ
 * raster up front; any failure aborts the lock so the user can fix the
 * problem on Step 4. */
export async function onLockBeforeNext(store) {
    const v = currentValue || (store.getStep('step4') || {}).template || {};
    const r = await treatmentsAPI.create({
        name: `${v.crop_code} MC template`,
        crop_code: v.crop_code,
        cultivar_code: v.cultivar_code || '',
        dssat_model: v.dssat_model || '',
        planting: v.planting || {},
        harvest: v.harvest || null,
        initial_conditions: v.initial_conditions || null,
        simulation_controls: v.simulation_controls || {},
        fertilizer: v.fertilizer || null,
        irrigation: v.irrigation || null,
        residue: v.residue || null,
        chemical: v.chemical || null,
        tillage: v.tillage || null,
    });
    const treatmentId = r.treatment.id;
    const fields = store.fields || [];
    const rows = fields.map((f, i) => ({
        treatment_id: treatmentId,
        field_id: f.id,
        ordering: i,
    }));
    const pairs = fields.map((f) => ({
        treatment_id: treatmentId,
        field_id: f.id,
        treatment_payload: v,
        field: f,
    }));
    // Auto-mode pre-resolution; throws on any failure.
    await resolveAutoPlantingDatesForPairs(store, pairs);
    await store.setTreatments(rows);
    pruneResolvedPlantingDates(store, pairs);
}
